"use client";

import * as React from "react";
import { type ColumnDef, flexRender, useTable } from "@tanstack/react-table";
import {
	columnVisibilityFeature,
	coreFeatures,
	createCoreRowModel,
	type RowData,
	rowSelectionFeature,
} from "@tanstack/table-core";
import {
	DndProvider,
	useSortableItem,
} from "../dnd/dnd.js";
import {
	SortableContext,
	verticalListSortingStrategy,
} from "@dnd-kit/sortable";
import type { DragEndEvent } from "@dnd-kit/core";
import {
	Table,
	TableBody,
	TableCaption,
	TableCell,
	TableHead,
	TableHeader,
	TableRow,
} from "../table/table.js";

/**
 * Feature set registered on the table instance.
 *
 * TanStack v9 is opt-in: an API is only present when its feature module is
 * registered, so each entry here is load-bearing for a call site below.
 * `coreRowModel` replaces v8's `getCoreRowModel()` option and now lives in
 * the feature slot. `rowSelectionFeature` backs `row.getIsSelected()`;
 * `columnVisibilityFeature` backs `row.getVisibleCells()`. Dropping either
 * one turns its call site into a type error rather than a silent no-op.
 *
 * Consumers that need sorting/filtering/pagination compose their own
 * feature set with `createSortedRowModel()` et al. and drive the table
 * themselves — this component intentionally stays core-only.
 */
export const dataTableFeatures = {
	...coreFeatures,
	rowSelectionFeature,
	columnVisibilityFeature,
	coreRowModel: createCoreRowModel(),
};

/** Feature set backing {@link DataTableProps.columns}. */
export type DataTableFeatures = typeof dataTableFeatures;

// Local declaration to avoid pulling @types/node into the package's
// type graph just for one NODE_ENV check.
declare const process: { env?: { NODE_ENV?: string } } | undefined;
function isProd(): boolean {
	return typeof process !== "undefined" && process?.env?.NODE_ENV === "production";
}

/**
 * Generic DataTable wrapper that renders a TanStack Table model using Hex Core's
 * Table primitives. Pass columns + data; use TanStack hooks for sorting,
 * filtering, pagination, row-selection as needed.
 *
 * Optional row-reorder support via `reorderableRows` + `onRowReorder` +
 * `getRowId`. When enabled, a drag-handle column is prepended; users can
 * drag rows to reorder, and `onRowReorder` fires with the new ID order.
 *
 * @template TData - Row data type. Cell value types are inferred per column by TanStack.
 *   Constrained to TanStack's `RowData` (an object or array shape) since v9.
 */
export interface DataTableProps<TData extends RowData> {
	columns: ColumnDef<DataTableFeatures, TData, unknown>[];
	data: TData[];
	/**
	 * Visible caption rendered below the table. Announced by screen readers
	 * when the user enters the table. Provide either `caption` or `aria-label`.
	 */
	caption?: React.ReactNode;
	/**
	 * Accessible label for the table when no visible caption is shown.
	 * Forwarded as `aria-label` on the underlying `<table>` element. Kebab-case
	 * to match the canonical ARIA prop convention used elsewhere in Hex Core.
	 */
	"aria-label"?: string;
	/**
	 * Enable drag-to-reorder rows. When true, a drag-handle column is added
	 * on the leading edge and rows can be reordered via mouse or keyboard.
	 * Requires `getRowId` (else throws — index-based IDs would break DnD on
	 * reorder because indices shift). Default false.
	 */
	reorderableRows?: boolean;
	/**
	 * Called with the next ordered list of row IDs after a drop. Consumer
	 * is responsible for re-deriving `data` in the new order. Required when
	 * `reorderableRows` is true.
	 */
	onRowReorder?: (orderedIds: string[]) => void;
	/**
	 * Stable row identifier. Required when `reorderableRows` is true.
	 * Forwarded to TanStack's `getRowId` so each row has a stable identity
	 * across renders (otherwise the row id is the array index, which shifts
	 * on reorder and breaks DnD).
	 */
	getRowId?: (row: TData, index: number) => string;
}

/**
 * Render a data-driven table from TanStack column definitions.
 * @param props - Columns, data, optional labelling, and optional reorder support
 * @returns A styled Table rendered from the TanStack row model
 */
export function DataTable<TData extends RowData>({
	columns,
	data,
	caption,
	"aria-label": ariaLabel,
	reorderableRows = false,
	onRowReorder,
	getRowId,
}: DataTableProps<TData>) {
	if (reorderableRows && !getRowId) {
		throw new Error(
			"DataTable: reorderableRows={true} requires getRowId. Without a stable row id, drag-and-drop breaks on reorder because TanStack's default index-based id shifts.",
		);
	}
	if (reorderableRows && !onRowReorder && !isProd()) {
		// eslint-disable-next-line no-console
		console.warn(
			"DataTable: reorderableRows={true} without onRowReorder — drops will animate but the new order is silently discarded.",
		);
	}

	const table = useTable({
		features: dataTableFeatures,
		data,
		columns,
		getRowId,
	});

	const onRowReorderRef = React.useRef(onRowReorder);
	onRowReorderRef.current = onRowReorder;

	const rows = table.getRowModel().rows;
	const rowIds = React.useMemo(() => rows.map((r) => r.id), [rows]);

	const handleDragEnd = React.useCallback(
		(event: DragEndEvent) => {
			const { active, over } = event;
			if (!over || active.id === over.id) return;
			const oldIndex = rowIds.indexOf(String(active.id));
			const newIndex = rowIds.indexOf(String(over.id));
			if (oldIndex === -1 || newIndex === -1) return;
			const next = [...rowIds];
			const [moved] = next.splice(oldIndex, 1);
			next.splice(newIndex, 0, moved);
			onRowReorderRef.current?.(next);
		},
		[rowIds],
	);

	const headerColCount = reorderableRows ? columns.length + 1 : columns.length;

	const tableInner = (
		<Table aria-label={ariaLabel}>
			{caption ? <TableCaption>{caption}</TableCaption> : null}
			<TableHeader>
				{table.getHeaderGroups().map((headerGroup) => (
					<TableRow key={headerGroup.id}>
						{reorderableRows ? <TableHead className="w-8" aria-hidden /> : null}
						{headerGroup.headers.map((header) => (
							<TableHead key={header.id}>
								{header.isPlaceholder
									? null
									: flexRender(header.column.columnDef.header, header.getContext())}
							</TableHead>
						))}
					</TableRow>
				))}
			</TableHeader>
			<TableBody>
				{rows.length ? (
					reorderableRows ? (
						<SortableContext items={rowIds} strategy={verticalListSortingStrategy}>
							{rows.map((row) => (
								<SortableDataRow key={row.id} id={row.id}>
									{row.getVisibleCells().map((cell) => (
										<TableCell key={cell.id}>
											{flexRender(cell.column.columnDef.cell, cell.getContext())}
										</TableCell>
									))}
								</SortableDataRow>
							))}
						</SortableContext>
					) : (
						rows.map((row) => (
							<TableRow key={row.id} data-state={row.getIsSelected() && "selected"}>
								{row.getVisibleCells().map((cell) => (
									<TableCell key={cell.id}>
										{flexRender(cell.column.columnDef.cell, cell.getContext())}
									</TableCell>
								))}
							</TableRow>
						))
					)
				) : (
					<TableRow>
						<TableCell colSpan={headerColCount} className="h-24 text-center">
							No results.
						</TableCell>
					</TableRow>
				)}
			</TableBody>
		</Table>
	);

	return (
		<div className="rounded-md border border-foreground/[0.08]">
			{reorderableRows ? (
				<DndProvider onDragEnd={handleDragEnd}>{tableInner}</DndProvider>
			) : (
				tableInner
			)}
		</div>
	);
}

/**
 * Internal: a single sortable row. Renders the leading drag handle as a
 * focusable button (KeyboardSensor picks up Space/Enter from it) and
 * forwards the rest of the cells.
 */
function SortableDataRow({
	id,
	children,
}: {
	id: string;
	children: React.ReactNode;
}) {
	const { setNodeRef, attributes, listeners, style, isDragging } = useSortableItem(id);
	// dnd-kit ships `role="button"` + `tabIndex=0` + `aria-pressed` in
	// `attributes` for default keyboard a11y on draggable elements. <tr>
	// has implicit row semantics — overriding them with role="button" +
	// tabIndex=0 breaks table navigation, and `aria-pressed` is invalid
	// per ARIA 1.2 on non-button roles (Axe will flag it). Strip all three;
	// the drag-handle button below carries the listeners and is the actual
	// keyboard pickup target. The aria-roledescription="sortable" + the
	// aria-describedby live-region pointer survive — both are load-bearing
	// for screen-reader announcements.
	const {
		role: _role,
		tabIndex: _tabIndex,
		"aria-pressed": _ariaPressed,
		...safeAttrs
	} = attributes as React.HTMLAttributes<HTMLElement> & {
		role?: string;
		tabIndex?: number;
		"aria-pressed"?: boolean | "true" | "false";
	};
	return (
		<TableRow
			ref={setNodeRef}
			style={style}
			data-row-id={id}
			data-dragging={isDragging}
			{...safeAttrs}
		>
			<TableCell className="w-8 cursor-grab active:cursor-grabbing">
				<button
					type="button"
					aria-label="Drag to reorder row"
					className="inline-flex h-6 w-6 items-center justify-center rounded text-muted-foreground hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
					{...listeners}
				>
					<svg aria-hidden viewBox="0 0 16 16" width="12" height="12" fill="currentColor">
						<circle cx="6" cy="3.5" r="1.25" />
						<circle cx="6" cy="8" r="1.25" />
						<circle cx="6" cy="12.5" r="1.25" />
						<circle cx="10" cy="3.5" r="1.25" />
						<circle cx="10" cy="8" r="1.25" />
						<circle cx="10" cy="12.5" r="1.25" />
					</svg>
				</button>
			</TableCell>
			{children}
		</TableRow>
	);
}

"use client";

import * as React from "react";
import {
	DndContext,
	type DndContextProps,
	KeyboardSensor,
	PointerSensor,
	closestCenter,
	useSensor,
	useSensors,
	type DragEndEvent,
} from "@dnd-kit/core";
import {
	SortableContext,
	arrayMove,
	horizontalListSortingStrategy,
	rectSortingStrategy,
	sortableKeyboardCoordinates,
	useSortable,
	verticalListSortingStrategy,
} from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import { cn } from "../../lib/utils.js";

/**
 * Composable drag-and-drop primitives for hex-core, built on @dnd-kit.
 *
 * Three exports:
 *   - `<DndProvider>` — root context with sensible defaults (PointerSensor +
 *     KeyboardSensor for out-of-box keyboard a11y, closestCenter collision).
 *     Pass `onDragEnd` to receive the active+over IDs.
 *   - `<SortableList items renderItem onChange>` — turnkey single-list wrapper.
 *     Handles its own DndContext + SortableContext + arrayMove for the 80%
 *     case (reorderable list of cards / rows / nav items).
 *   - `useSortableItem(id)` — the headless hook for advanced consumers
 *     (Kanban cards, DataTable rows, Tree nodes). Returns the dnd-kit refs +
 *     attributes + listeners + a CSS-ready transform.
 *
 * Heavy peer: `@dnd-kit/core` + `@dnd-kit/sortable` + `@dnd-kit/utilities`
 * (~43 KB gzip total). Install via the hex-core CLI's `add` flow.
 *
 * Re-exports the three sortable strategies (`vertical`, `horizontal`, `rect`)
 * + `arrayMove` so consumers don't add @dnd-kit to their import list.
 */

export type SortStrategy = "vertical" | "horizontal" | "rect";

const STRATEGIES = {
	vertical: verticalListSortingStrategy,
	horizontal: horizontalListSortingStrategy,
	rect: rectSortingStrategy,
} as const;

export interface DndProviderProps
	extends Omit<DndContextProps, "sensors" | "collisionDetection"> {
	children: React.ReactNode;
}

/**
 * Root drag-and-drop context. Wires up sensible default sensors
 * (Pointer + Keyboard for keyboard a11y) and closestCenter collision.
 * @param props - Pass through to dnd-kit's DndContext (e.g. onDragEnd, onDragStart, modifiers)
 * @returns A DndContext provider with hex-core defaults
 */
function DndProvider({ children, ...rest }: DndProviderProps) {
	const sensors = useSensors(
		useSensor(PointerSensor, {
			activationConstraint: { distance: 4 },
		}),
		useSensor(KeyboardSensor, {
			coordinateGetter: sortableKeyboardCoordinates,
		}),
	);

	return (
		<DndContext sensors={sensors} collisionDetection={closestCenter} {...rest}>
			{children}
		</DndContext>
	);
}

export interface SortableListProps<T extends { id: string | number }>
	extends Omit<React.HTMLAttributes<HTMLDivElement>, "children" | "onChange"> {
	/** Items to render. Each must carry a stable `id` field. */
	items: T[];
	/** Render function for one item. Wrap the returned node with `useSortableItem` for the drag wiring. */
	renderItem: (item: T, index: number) => React.ReactNode;
	/** Called with the new item array after a drop. */
	onChange: (next: T[]) => void;
	/** Sortable strategy. Default `"vertical"`. */
	strategy?: SortStrategy;
}

/**
 * Turnkey sortable list. Handles its own DndContext + SortableContext.
 *
 * The `renderItem` callback typically returns a wrapper that calls
 * `useSortableItem(item.id)` and spreads its refs/listeners onto a
 * draggable root element.
 *
 * @example
 * <SortableList
 *   items={items}
 *   onChange={setItems}
 *   renderItem={(item) => (
 *     <SortableCard id={item.id}>{item.title}</SortableCard>
 *   )}
 * />
 */
function SortableList<T extends { id: string | number }>({
	items,
	renderItem,
	onChange,
	strategy = "vertical",
	className,
	...rest
}: SortableListProps<T>) {
	const onChangeRef = React.useRef(onChange);
	onChangeRef.current = onChange;

	const handleDragEnd = React.useCallback(
		(event: DragEndEvent) => {
			const { active, over } = event;
			if (!over || active.id === over.id) return;
			const oldIndex = items.findIndex((it) => it.id === active.id);
			const newIndex = items.findIndex((it) => it.id === over.id);
			if (oldIndex === -1 || newIndex === -1) return;
			onChangeRef.current(arrayMove(items, oldIndex, newIndex));
		},
		[items],
	);

	const ids = React.useMemo(() => items.map((it) => it.id), [items]);

	return (
		<DndProvider onDragEnd={handleDragEnd}>
			<SortableContext items={ids} strategy={STRATEGIES[strategy]}>
				<div
					{...rest}
					data-hex-sortable-list
					data-strategy={strategy}
					className={cn(
						strategy === "horizontal" ? "flex gap-2" : "flex flex-col gap-2",
						className,
					)}
				>
					{items.map((item, index) => (
						<React.Fragment key={item.id}>{renderItem(item, index)}</React.Fragment>
					))}
				</div>
			</SortableContext>
		</DndProvider>
	);
}

export interface UseSortableItemReturn {
	/** Attach to the outer draggable element. */
	setNodeRef: (element: HTMLElement | null) => void;
	/** Spread onto the draggable root for ARIA + keyboard wiring. */
	attributes: React.HTMLAttributes<HTMLElement>;
	/** Spread onto the drag handle (or the draggable root if no separate handle). */
	listeners: React.DOMAttributes<HTMLElement> | undefined;
	/** Pre-computed `style` with the active drag transform. Apply to `setNodeRef` element. */
	style: React.CSSProperties;
	/** True while this item is being dragged. */
	isDragging: boolean;
}

/**
 * Headless hook for one sortable item. Wire the returned refs/listeners
 * onto your draggable root (and optionally a separate drag handle via
 * the `listeners` value).
 *
 * Must be called inside a `<SortableContext>` (provided automatically by
 * `<SortableList>` or `<Kanban>`, manually by advanced consumers).
 *
 * @param id - Stable identifier for this item (must match the SortableContext items array)
 * @returns Refs + attributes + listeners + style + isDragging flag
 */
function useSortableItem(id: string | number): UseSortableItemReturn {
	const { setNodeRef, attributes, listeners, transform, transition, isDragging } = useSortable({
		id,
	});

	const style: React.CSSProperties = {
		transform: CSS.Transform.toString(transform),
		transition,
		opacity: isDragging ? 0.5 : 1,
	};

	return {
		setNodeRef,
		attributes,
		listeners,
		style,
		isDragging,
	};
}

export {
	DndProvider,
	SortableList,
	useSortableItem,
	// Re-exports so consumers don't have to add @dnd-kit/sortable to their imports.
	arrayMove,
	verticalListSortingStrategy,
	horizontalListSortingStrategy,
	rectSortingStrategy,
};

import * as React from "react";
import { cn } from "../../lib/utils.js";

/** A responsive container + styled HTML table. */
const Table = React.forwardRef<HTMLTableElement, React.HTMLAttributes<HTMLTableElement>>(
	({ className, ...props }, ref) => (
		<div className="relative w-full overflow-auto">
			<table
				ref={ref}
				className={cn("w-full caption-bottom text-sm", className)}
				{...props}
			/>
		</div>
	),
);
Table.displayName = "Table";

/** `<thead>` wrapper with bottom border. */
const TableHeader = React.forwardRef<
	HTMLTableSectionElement,
	React.HTMLAttributes<HTMLTableSectionElement>
>(({ className, ...props }, ref) => (
	<thead ref={ref} className={cn("[&_tr]:border-b [&_tr]:border-b-foreground/[0.08]", className)} {...props} />
));
TableHeader.displayName = "TableHeader";

/** `<tbody>` wrapper removing bottom border on last row. */
const TableBody = React.forwardRef<
	HTMLTableSectionElement,
	React.HTMLAttributes<HTMLTableSectionElement>
>(({ className, ...props }, ref) => (
	<tbody ref={ref} className={cn("[&_tr:last-child]:border-0", className)} {...props} />
));
TableBody.displayName = "TableBody";

/** `<tfoot>` wrapper with muted background. */
const TableFooter = React.forwardRef<
	HTMLTableSectionElement,
	React.HTMLAttributes<HTMLTableSectionElement>
>(({ className, ...props }, ref) => (
	<tfoot
		ref={ref}
		className={cn(
			"border-t border-t-foreground/[0.08] bg-muted/50 font-medium [&>tr]:last:border-b-0",
			className,
		)}
		{...props}
	/>
));
TableFooter.displayName = "TableFooter";

/** `<tr>` with hover + selected states. */
const TableRow = React.forwardRef<
	HTMLTableRowElement,
	React.HTMLAttributes<HTMLTableRowElement>
>(({ className, ...props }, ref) => (
	<tr
		ref={ref}
		className={cn(
			"border-b border-b-foreground/[0.08] transition-all duration-[var(--duration-normal,200ms)] ease-out hover:bg-muted/50 data-[state=selected]:bg-muted",
			className,
		)}
		{...props}
	/>
));
TableRow.displayName = "TableRow";

/** `<th>` with left-aligned muted text. */
const TableHead = React.forwardRef<
	HTMLTableCellElement,
	React.ThHTMLAttributes<HTMLTableCellElement>
>(({ className, ...props }, ref) => (
	<th
		ref={ref}
		className={cn(
			"h-[var(--control-height-md,2.5rem)] px-[var(--space-4,1rem)] text-left align-middle font-medium text-muted-foreground [&:has([role=checkbox])]:pr-0",
			className,
		)}
		{...props}
	/>
));
TableHead.displayName = "TableHead";

/** `<td>` with consistent padding. */
const TableCell = React.forwardRef<
	HTMLTableCellElement,
	React.TdHTMLAttributes<HTMLTableCellElement>
>(({ className, ...props }, ref) => (
	<td
		ref={ref}
		className={cn("p-[var(--space-4,1rem)] align-middle [&:has([role=checkbox])]:pr-0", className)}
		{...props}
	/>
));
TableCell.displayName = "TableCell";

/**
 * Visible `<caption>` rendered below the table. The parent `<Table>` sets
 * `caption-bottom`, so the caption is announced first by screen readers when
 * entering the table, then visually placed below the rows.
 */
const TableCaption = React.forwardRef<
	HTMLTableCaptionElement,
	React.HTMLAttributes<HTMLTableCaptionElement>
>(({ className, ...props }, ref) => (
	<caption
		ref={ref}
		className={cn(
			"caption-bottom mt-[var(--space-4,1rem)] text-sm text-muted-foreground",
			className,
		)}
		{...props}
	/>
));
TableCaption.displayName = "TableCaption";

export {
	Table,
	TableHeader,
	TableBody,
	TableFooter,
	TableHead,
	TableRow,
	TableCell,
	TableCaption,
};

/**
 * Color conversion utilities for the HSL-triplet token format used across
 * `@hex-core/tokens` themes (`H S% L%`, e.g. `"240 5.9% 10%"` — no `hsl()`
 * wrapper, no commas).
 *
 * The triplet is the round-trip-safe serialization for Hex Core: tokens flow
 * triplet → CSS `hsl(var(--token))` → rendered color, and the ColorPicker
 * component edits triplets directly. Hex/RGB conversions are display
 * adapters, not the source of truth.
 */

/** Parsed HSL components. `h` is degrees (0–360); `s` and `l` are percentages (0–100). */
export interface HslTriplet {
	h: number;
	s: number;
	l: number;
}

/** Parsed RGB components. Each channel is 0–255. */
export interface RgbColor {
	r: number;
	g: number;
	b: number;
}

/**
 * Parse an HSL triplet string into numeric components.
 *
 * Note: malformed input silently coerces to `{0,0,0}` (pure black) rather than
 * returning an error signal. Callers that need to distinguish "user typed
 * black" from "user typed garbage" should validate the input format first.
 * `hexToHslTriplet` returns `null` for malformed hex; this asymmetry is
 * intentional — triplets feed CSS variables where any non-color value would
 * already break rendering.
 *
 * @param triplet - String in the form `"<H> <S>% <L>%"` (e.g. `"240 5.9% 10%"`).
 * @returns Numeric components, or `{0,0,0}` if the input is malformed.
 */
export function parseHslTriplet(triplet: string): HslTriplet {
	const parts = triplet.trim().split(/\s+/);
	return {
		h: Number.parseFloat(parts[0]) || 0,
		s: Number.parseFloat(parts[1]) || 0,
		l: Number.parseFloat(parts[2]) || 0,
	};
}

/**
 * Format HSL components into an HSL triplet string (the canonical token format).
 * @param hsl - Numeric components.
 * @returns Triplet in the form `"<H> <S>% <L>%"`.
 */
export function formatHslTriplet({ h, s, l }: HslTriplet): string {
	// Tolerant integer check: rgbToHsl can produce values like 5.0000000001 due
	// to float arithmetic; format those as "5" rather than "5.0".
	const round = (n: number) =>
		Math.abs(n - Math.round(n)) < 1e-6 ? `${Math.round(n)}` : n.toFixed(1);
	return `${Math.round(h)} ${round(s)}% ${round(l)}%`;
}

/**
 * Convert HSL components to RGB.
 * @param h - Hue (0–360).
 * @param s - Saturation (0–100).
 * @param l - Lightness (0–100).
 * @returns RGB channels (0–255, rounded).
 */
export function hslToRgb(h: number, s: number, l: number): RgbColor {
	const sN = s / 100;
	const lN = l / 100;
	const k = (n: number) => (n + h / 30) % 12;
	const a = sN * Math.min(lN, 1 - lN);
	const f = (n: number) => lN - a * Math.max(-1, Math.min(k(n) - 3, 9 - k(n), 1));
	return {
		r: Math.round(255 * f(0)),
		g: Math.round(255 * f(8)),
		b: Math.round(255 * f(4)),
	};
}

/**
 * Convert RGB components to HSL.
 * @param r - Red (0–255).
 * @param g - Green (0–255).
 * @param b - Blue (0–255).
 * @returns HSL components (h: 0–360, s: 0–100, l: 0–100).
 */
export function rgbToHsl(r: number, g: number, b: number): HslTriplet {
	const rN = r / 255;
	const gN = g / 255;
	const bN = b / 255;
	const max = Math.max(rN, gN, bN);
	const min = Math.min(rN, gN, bN);
	let h = 0;
	let s = 0;
	const l = (max + min) / 2;
	if (max !== min) {
		const d = max - min;
		s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
		if (max === rN) h = (gN - bN) / d + (gN < bN ? 6 : 0);
		else if (max === gN) h = (bN - rN) / d + 2;
		else h = (rN - gN) / d + 4;
		h /= 6;
	}
	return { h: h * 360, s: s * 100, l: l * 100 };
}

/**
 * Convert an HSL triplet to a 6-digit hex string.
 * @param triplet - HSL triplet (e.g. `"240 5.9% 10%"`).
 * @returns Lowercase hex string with leading `#` (e.g. `"#181a1f"`).
 */
export function hslTripletToHex(triplet: string): string {
	const { h, s, l } = parseHslTriplet(triplet);
	const { r, g, b } = hslToRgb(h, s, l);
	const toHex = (n: number) => n.toString(16).padStart(2, "0");
	return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
}

/**
 * Convert a hex string to an HSL triplet.
 * Accepts 3-digit (`#abc`) or 6-digit (`#aabbcc`) hex with optional `#`.
 * @param hex - Hex color string.
 * @returns HSL triplet, or `null` if the input is malformed.
 */
export function hexToHslTriplet(hex: string): string | null {
	const clean = hex.trim().replace(/^#/, "");
	let normalized: string;
	if (/^[0-9a-fA-F]{3}$/.test(clean)) {
		normalized = clean
			.split("")
			.map((c) => c + c)
			.join("");
	} else if (/^[0-9a-fA-F]{6}$/.test(clean)) {
		normalized = clean;
	} else {
		return null;
	}
	const r = Number.parseInt(normalized.slice(0, 2), 16);
	const g = Number.parseInt(normalized.slice(2, 4), 16);
	const b = Number.parseInt(normalized.slice(4, 6), 16);
	return formatHslTriplet(rgbToHsl(r, g, b));
}

import { type ClassValue, clsx } from "clsx";
